const net = require('net');
const { parseRequestHead } = require('./request');
const { BAD_REQUEST_RESPONSE, routeRequest } = require('./router');

const PORT = process.env.PORT || 8080;
const DEFAULT_MAX_REQUEST_LINE_BYTES = 8192;
const MAX_HEAD_BYTES = 65536;
const MAX_BODY_BYTES = 1048576;
const LINE_END = '\r\n';
const HEAD_END = '\r\n\r\n';

const readMaxRequestLineBytes = () => {
  const configuredValue = process.env.MAX_REQUEST_LINE_BYTES ?? DEFAULT_MAX_REQUEST_LINE_BYTES;
  const maxRequestLineBytes = Number(configuredValue);
  if (!Number.isSafeInteger(maxRequestLineBytes) || maxRequestLineBytes <= 0) {
    throw new Error(`MAX_REQUEST_LINE_BYTES must be a positive integer, got "${configuredValue}"`);
  }
  return maxRequestLineBytes;
};

const MAX_REQUEST_LINE_BYTES = readMaxRequestLineBytes();

const hasRequestLine = (receivedBytes) =>
  receivedBytes.subarray(0, MAX_REQUEST_LINE_BYTES).indexOf(LINE_END) !== -1;

const server = net.createServer((conn) => {
  let receivedBytes = Buffer.alloc(0);
  let head = null;
  let bodyStart = 0;

  const sendResponse = (response) => conn.end(response, 'latin1');

  const handleData = () => {
    if (!hasRequestLine(receivedBytes)) {
      if (receivedBytes.length >= MAX_REQUEST_LINE_BYTES) sendResponse(BAD_REQUEST_RESPONSE);
      return;
    }

    if (head === null) {
      const headEnd = receivedBytes.indexOf(HEAD_END);
      if (headEnd === -1) {
        if (receivedBytes.length >= MAX_HEAD_BYTES) sendResponse(BAD_REQUEST_RESPONSE);
        return;
      }
      head = headEnd <= MAX_HEAD_BYTES
        ? parseRequestHead(receivedBytes.toString('latin1', 0, headEnd), MAX_BODY_BYTES)
        : null;
      if (head === null) {
        sendResponse(BAD_REQUEST_RESPONSE);
        return;
      }
      bodyStart = headEnd + HEAD_END.length;
    }

    if (receivedBytes.length >= bodyStart + head.contentLength) {
      const body = receivedBytes.subarray(bodyStart, bodyStart + head.contentLength);
      sendResponse(routeRequest({ ...head, body }));
    }
  };

  conn.on('error', () => {});
  conn.on('data', (chunk) => {
    if (conn.writableEnded) return;
    receivedBytes = Buffer.concat([receivedBytes, chunk]);
    handleData();
  });
  conn.on('end', () => {
    if (!conn.writableEnded) sendResponse(BAD_REQUEST_RESPONSE);
  });
});

server.listen(PORT);

